fn installed_apps()->Vec<V>{let mut out=HashMap::new();let roots=[std::env::var("ProgramData").unwrap_or_else(|_|"C:\\ProgramData".into()),std::env::var("APPDATA").unwrap_or_default()];for root in roots{let p=PathBuf::from(root).join("Microsoft").join("Windows").join("Start Menu").join("Programs");walk_lnk(&p,&mut out,0);}let mut v:Vec<_>=out.into_values().collect();v.sort_by_key(|x|s(x,"name").to_lowercase());v}
#[cfg(windows)]
fn walk_lnk(p:&Path,out:&mut HashMap<String,V>,depth:usize){if depth>12{return}if let Ok(dir)=fs::read_dir(p){for f in dir.flatten(){let path=f.path();if path.is_dir(){walk_lnk(&path,out,depth+1)}else if path.extension().and_then(|x|x.to_str()).map(|x|x.eq_ignore_ascii_case("lnk")).unwrap_or(false){let n=path.file_stem().unwrap_or_default().to_string_lossy().to_string();if !["uninstall","disinstall","readme","help","manual","license","documentation","release notes","website","sito web"].iter().any(|x|n.to_lowercase().contains(x)){out.entry(n.to_lowercase()).or_insert(json!({"name":n,"path":path.to_string_lossy()}));}}}}}
#[cfg(not(windows))]
fn installed_apps()->Vec<V>{Vec::new()}
fn app_icon(p:&str)->Res<String>{#[cfg(windows)]{if !Path::new(p).exists(){return Err("File non trovato".into())}let ps=r#"Add-Type -AssemblyName System.Drawing;$p=$env:JA_PATH;if($p -like '*.lnk'){try{$t=(New-Object -ComObject WScript.Shell).CreateShortcut($p).TargetPath;if($t -and (Test-Path $t)){$p=$t}}catch{}};$i=[System.Drawing.Icon]::ExtractAssociatedIcon($p);$m=New-Object IO.MemoryStream;$i.ToBitmap().Save($m,[System.Drawing.Imaging.ImageFormat]::Png);[Convert]::ToBase64String($m.ToArray())"#;let out=std::process::Command::new("powershell").args(["-NoProfile","-NonInteractive","-Command",ps]).env("JA_PATH",p).output().map_err(err)?;let b=String::from_utf8_lossy(&out.stdout).trim().to_string();return Ok(if b.len()>100{format!("data:image/png;base64,{b}")}else{String::new()})}#[cfg(not(windows))]{let _=p;Ok(String::new())}}
#[cfg(windows)]
fn autostart_get()->bool{std::process::Command::new("reg").args(["query",r"HKCU\Software\Microsoft\Windows\CurrentVersion\Run","/v","JesseArchive"]).output().map(|o|o.status.success()).unwrap_or(false)}
#[cfg(not(windows))]
fn autostart_get()->bool{false}
#[cfg(windows)]
fn autostart_set(on:bool)->Res<()>{let path=std::env::current_exe().map_err(err)?;let value=format!("\"{}\" --background",path.display());let mut cmd=std::process::Command::new("reg");cmd.args(if on{vec!["add",r"HKCU\Software\Microsoft\Windows\CurrentVersion\Run","/v","JesseArchive","/t","REG_SZ","/d",&value,"/f"]}else{vec!["delete",r"HKCU\Software\Microsoft\Windows\CurrentVersion\Run","/v","JesseArchive","/f"]});let result=cmd.output().map_err(err)?;if !result.status.success()&&on{return Err("Impossibile modificare l'avvio automatico".into())}Ok(())}
#[cfg(not(windows))]
fn autostart_set(_on:bool)->Res<()>{Err("Solo Windows".into())}

#[cfg(test)]mod tests{
use super::*;
#[test]fn kdf_legacy(){let salt=[0u8;16];let v=kdf("testing-scrypt",&salt).unwrap();assert_eq!(v.len(),32)}
#[test]fn aes_roundtrip(){let k=rand_bytes::<32>();let plain=b"synthetic secret";assert_eq!(unseal(&k,&seal(&k,plain).unwrap()).unwrap(),plain);let mut bad=seal(&k,plain).unwrap();bad.push('a');assert!(unseal(&k,&bad).is_err())}
#[test]fn merge_preserves_unknown(){let mut a=empty();a["items"]=json!([{"id":"first","created":1.,"updated":1.,"x_legacy":7}]);let mut b=empty();b["items"]=json!([{"id":"first","created":1.,"updated":2.,"x_legacy":8}]);assert!(merge_data(&mut a,&b));assert_eq!(a["items"][0]["x_legacy"],8)}
#[test]fn totp_rfc(){assert_eq!(totp("GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ",59).unwrap(),"287082")}
}
#[cfg(test)]mod legacy_python_vectors {
use super::*;
#[test]fn decrypt_python_generated_v1(){let f:V=serde_json::from_str(include_str!("../../../fixtures/legacy_v1_synthetic.json")).unwrap();let h=&f["header"];let got=kdf(s(&f,"password"),&decode(h,"salt").unwrap()).unwrap();assert_eq!(hex::encode(&*got),s(&f,"expected_kdf_hex"));let dek=unseal(&got,s(h,"wrap")).unwrap();assert_eq!(hex::encode(&dek),s(&f,"expected_dek_hex"));let dek:[u8;32]=dek.try_into().unwrap();let plain=unseal(&dek,s(h,"data")).unwrap();let d:V=serde_json::from_slice(&plain).unwrap();assert_eq!(d,f["expected_data"])}
}
